Q: How to make a generalized template class? A: <p><code>get</code> and <code>reset</code> should have template index, and not function parameter for index:</p>
<pre><code>template &lt;std::size_t INDEX&gt;
auto get()
{
    if constexpr (INDEX == 0) {
        return first;
    } else if constexpr (INDEX == 1) {
        return second;
    } else if constexpr (INDEX == 2) {
        return third;
    } else {
        static_assert(false, &quot;wrong index&quot;);
    }
}

template &lt;std::size_t INDEX, tenmplate T&gt;
void reset(T&amp;&amp; value)
{
    if constexpr (INDEX == 0) {
        first = std::forward&lt;T&gt;(value);
    } else if constexpr (INDEX == 1) {
        second = std::forward&lt;T&gt;(value);
    } else if constexpr (INDEX == 2) {
        third = std::forward&lt;T&gt;(value);
    } else {
        static_assert(false, &quot;wrong index&quot;);
    }
}
</code></pre>
<p>Usage would be:</p>
<pre><code>s.reset&lt;0&gt;(5)

std::cout &lt;&lt; s.get&lt;0&gt;();
</code></pre>
